fn binary_search(a: &[i32], key: i32) -> usize {
    let mut left = 0;
    let mut right = a.len();

    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < key {
            left = mid + 1;
        } else {
            right = mid;
        }
    }

    left
}

fn main() {
    let arr = [1, 2, 4, 5, 5, 6];
    let target = 5;
    let index = binary_search(&arr, target);
    println!("The insertion index for {} is {}", target, index); // Output: The insertion index for 5 is 3
}